import functools

def count_calls(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return fn(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@count_calls
def add(a, b): return a + b

import functools

def non_negative(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        for v in list(args) + list(kwargs.values()):
            if isinstance(v, (int, float)) and v < 0:
                raise ValueError('negative value not allowed')
        return fn(*args, **kwargs)
    return wrapper

import functools

def memo(fn):
    cache = {}
    @functools.wraps(fn)
    def wrapper(*args):
        if args not in cache:
            cache[args] = fn(*args)
        return cache[args]
    wrapper.cache = cache
    return wrapper

import functools, time, random

def retry(attempts=3, base=0.2, exc=(TimeoutError, ConnectionError)):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for i in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exc:
                    if i == attempts - 1: raise
                    time.sleep(base * 2 ** i + random.uniform(0, base))
        return wrapper
    return deco

def where(**conds):
    def match(row):
        return all(row.get(k) == v for k, v in conds.items())
    return match

