import time

def throttle(max_per_sec=5):
    min_gap = 1.0 / max_per_sec
    last = [0.0]
    def wait():
        delta = time.perf_counter() - last[0]
        if delta < min_gap:
            time.sleep(min_gap - delta)
        last[0] = time.perf_counter()
    return wait

import functools, time, logging

def timed(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        t0 = time.perf_counter()
        try:
            return fn(*args, **kwargs)
        finally:
            ms = (time.perf_counter() - t0) * 1000
            if ms > 100:
                logging.warning('%s slow: %.1fms', fn.__name__, ms)
    return wrapper

def deco(fn):
    @functools.wraps(fn)
    def wrapper(*a, **kw):
        return fn(*a, **kw)
    return wrapper
